"""Sample records."""


class Sample:
    def __init__(self, batch, dose):
        self.batch = batch
        self.dose = dose

    def __repr__(self):
        return "Sample(%r, %r)" % (self.batch, self.dose)


ROWS = [('b4', 23), ('b3', 21), ('b2', 16), ('b1', 50), ('b3', 46)]


def load_samples():
    """Yield the stored samples one at a time."""
    for batch, dose in ROWS:
        yield Sample(batch, dose)

