"""Billing for samples. Rate lookups are billed, so the charge is remembered."""
import rates


class SampleBill:
    def __init__(self):
        self._samples = []
        self._charge = None

    def add(self, sample):
        """Add one sample to the bill."""
        self._samples.append(sample)

    def charge(self):
        """Return the total charge: dose times the rate for each sample's batch.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.dose * rates.rate_for(x.batch) for x in self._samples)
        return self._charge

